function pickFlowWeighted(flows) {
    if (!flows || flows.length === 0) return null;
    const total = flows.reduce((s, f) => s + (f.weight ?? 1), 0);
    let r = Math.random() * total;
    for (const f of flows) { r -= (f.weight ?? 1); if (r <= 0) return f; }
    return flows[flows.length - 1];
  }

  function buildFlowLine(f) {
    const lines = [];
    lines.push('→ flow_name (cópialo EXACTO, carácter por carácter, no lo traduzcas ni lo parafrasees):');
    lines.push('  ' + f.flow_ns);
    lines.push('');
    if (f.media_type) {
      lines.push('  Tipo: [' + f.media_type + ']');
    }
    const condition = f.usage_condition || f.description || '';
    if (condition) {
      lines.push('  Cuándo: ' + condition);
    }
    if (f.content_description) {
      lines.push('  Contenido: ' + f.content_description);
    }
    return lines.join('\n');
  }

  function buildCrmBlock(followupsSent, maxFollowups, history, stageName, stageObjective) {
    const lines = ['# ESTADO CRM DEL LEAD'];
    lines.push('Etapa: ' + stageName + (stageObjective ? ' — ' + stageObjective : ''));
    if (followupsSent === 0) {
      lines.push('Seguimientos enviados: ninguno. Es el primer contacto o acaba de responder.');
    } else {
      lines.push('Seguimientos enviados sin respuesta: ' + followupsSent + ' de ' + maxFollowups + ' máximo.');
      (history ?? []).forEach(function(h) {
        const daysAgo = Math.round((Date.now() - new Date(h.sent_at)) / 86400000);
        const responded = h.responded_at ? ' <- respondió' : ' (sin respuesta)';
        lines.push('  - #' + h.seq + ' hace ' + daysAgo + ' día(s)' + responded);
      });
      if (followupsSent >= maxFollowups) {
        lines.push('Límite de seguimientos alcanzado. Si no hay interés real en este turno, usa set_stage("disqualified",...).');
      } else {
        lines.push('Está respondiendo tras un silencio. Sé cálido; no menciones los seguimientos.');
      }
    }
    return lines.join('\n');
  }

  const raw = $('Webhook').first().json;
  const body = raw.body ?? raw;

  const messages = body.messages
    .map(function(m) {
      if (m.reply_type === 'thumbs_up') return '👍 [el contacto reaccionó con pulgar arriba]';
      if (m.media_urls && m.media_urls.length > 0 && !m.text) return '[contenido multimedia recibido — no se puede leer]';
      return m.text || '[mensaje sin texto]';
    })
    .filter(Boolean)
    .join('\n');

  const sub = body.subscriber;
  const subscriberName = sub.display_name || sub.ig_username || 'la persona';
  const currentStage = sub.lead_stage || (sub.metadata && sub.metadata.stage) || 'A';

  const stageConfig = $('Get Stage Config').first() ? $('Get Stage Config').first().json : {};
  const flows = Array.isArray(stageConfig.flows) ? stageConfig.flows : [];
  const stageDesc = stageConfig.description || '';
  const maxFollowups = stageConfig.max_followups || 3;

  const selectedFlow = pickFlowWeighted(flows);
  const flowsSection = selectedFlow
    ? buildFlowLine(selectedFlow)
    : '(no hay contenido multimedia para esta etapa — responde solo con texto)';

  const crm = $('Get Subscriber CRM Context').first() ? $('Get Subscriber CRM Context').first().json : {};
  const followupsSent = crm.followups_sent || 0;
  const history = Array.isArray(crm.followup_history) ? crm.followup_history : [];
  const stageName = crm.stage_name || stageConfig.display_name || currentStage;
  const stageObjective = crm.stage_objective || stageDesc;
  const crmBlock = buildCrmBlock(followupsSent, maxFollowups, history, stageName, stageObjective);

  const igCtx = body.instagram_context || {};
  const lastSeen = igCtx.last_seen || null;
  const lastInteraction = igCtx.last_interaction || null;
  const signals = (sub.metadata && sub.metadata.signals) || (body.lead_state && body.lead_state.signals) || null;
  const calendlyUrl = (body.tenant && body.tenant.config && body.tenant.config.calendly_url) || '';
  //const staticPrompt = (body.tenant && body.tenant.config && body.tenant.config.system_prompt) || '';
  const staticPrompt = $('System Prompt').first()?.json?.staticPrompt || '';

  const contextLines = [
    'La persona se llama: ' + subscriberName,
    'Etapa actual del lead: ' + currentStage + (stageDesc ? ' — ' + stageDesc : ''),
  ];
  if (lastSeen)        contextLines.push('Última vez activa en Instagram: ' + lastSeen);
  if (lastInteraction) contextLines.push('Última interacción contigo: ' + lastInteraction);
  if (signals)         contextLines.push('Señales detectadas en turnos anteriores: ' + (typeof signals === 'string' ? signals :
  JSON.stringify(signals)));
  if (calendlyUrl && currentStage === 'B') {
       contextLines.push('Link de Calendly para enviar AHORA MISMO: ' + calendlyUrl);
  }
  contextLines.push('');
  contextLines.push('# CONTENIDO DISPONIBLE para esta etapa');
  contextLines.push('Usa la herramienta trigger_manychat_flow pasando el flow_name EXACTO de abajo.');
  contextLines.push('');
  contextLines.push(flowsSection);
  contextLines.push('');
  contextLines.push(crmBlock);

  const dynamicContext = contextLines.join('\n');
  const systemPrompt = staticPrompt
    ? staticPrompt + '\n\n# CONTEXTO\n' + dynamicContext
    : 'Eres Alex, el setter de Quantum Creators. Sé cálido y breve, máximo 2 frases, tutea siempre. Nunca digas que eres un bot ni des precios.\n\n# CONTEXTO\n' + dynamicContext;

  return [{
    json: {
      chatInput: messages,
      systemPrompt: systemPrompt,
      subscriberId: sub.manychat_subscriber_id,
      subscriberDbId: sub.id,
      tenantDbId: (body.tenant && body.tenant.id) || '',
      mcApiKey: (body.tenant && body.tenant.config && body.tenant.config.manychat_api_key) || '',
      conversationId: body.conversation.id,
      turnId: body.turn_id,
      currentStage: currentStage,
      callbackUrl: body.callback_url,
      callbackToken: body.callback_token,
    }
  }];

return [{
  json: {
    turn_id: $('Build Context').first().json.turnId,
    status: 'completed',
    response_text: $('AI Agent').first().json.output,
    callbackUrl: $('Build Context').first().json.callbackUrl,
    callbackToken: $('Build Context').first().json.callbackToken
  }
}];

const { new_stage, reason, evidence } = query;

  const subscriberDbId = $('Build Context').first().json.subscriberDbId;
  const turnId         = $('Build Context').first().json.turnId;
  const callbackToken  = $('Build Context').first().json.callbackToken;

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', 
      url: `https://api.revolicord.com/admin/leads/${subscriberDbId}/stage`,
      headers: {
        Authorization: `Bearer ${callbackToken}`,
        'Content-Type': 'application/json',
      },
      body: { new_stage, reason, evidence, turn_id: turnId },
      json: true,
      returnFullResponse: true,
    });

    if (res.statusCode === 200) {
      const { stage, changed, from } = res.body;
      return changed
        ? `ok: stage changed ${from} → ${stage}`
        : `ok: stage already ${stage} (no change)`;
    }   
    return `error: HTTP ${res.statusCode} — ${JSON.stringify(res.body)}`;
  } catch (err) {
    return `error: ${err.message ?? 'set_stage request failed'}`;
  }

const { flow_name } = query;

  // 1) Validación defensiva del parámetro que pasó el LLM
  if (!flow_name || typeof flow_name !== 'string') {
    return `error: parámetro flow_name ausente o no es string. Recibido: ${JSON.stringify(flow_name)}`;
  }
  if (!/^content[0-9]{14}_[0-9]+$/.test(flow_name)) {
    return `error: flow_name "${flow_name}" no cumple el formato (content + 14 dígitos + _ + dígitos). Copia el ns EXACTO del bloque CONTENIDO
  DISPONIBLE del prompt — no inventes ni traduzcas.`;
  }

  // 2) Datos dinámicos del turno (vienen de Build Context)
  let subscriberId, mcApiKey;
  try {
    const ctx = $('Build Context').first().json;
    subscriberId = ctx.subscriberId;
    mcApiKey     = ctx.mcApiKey;
  } catch (err) {
    return `error interno: no se pudo leer Build Context (${err.message ?? err})`;
  }
  if (!subscriberId) return `error interno: subscriberId ausente en Build Context`;
  if (!mcApiKey)     return `error interno: mcApiKey ausente en Build Context`;

  // 3) Call a ManyChat (mismo patrón que validamos en el flow de test)
  const url = 'https://api.manychat.com/fb/sending/sendFlow';
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: url,
      headers: {
        Authorization: `Bearer ${mcApiKey}`,
        'Content-Type': 'application/json',
      },
      body: { subscriber_id: subscriberId, flow_ns: flow_name },
      json: true,
      returnFullResponse: true,
    });

    if (res.statusCode === 200 && res.body && res.body.status === 'success') {
      return `ok: flow ${flow_name} enviado a subscriber ${subscriberId}`;
    }
    return `error: ManyChat respondió ${res.statusCode} — ${JSON.stringify(res.body)}`;
  } catch (err) {
    const status = err.statusCode || err.httpCode || 'unknown';
    const body   = err.response?.body || err.body || err.message || String(err);
    return `error: ManyChat ${status} — ${typeof body === 'string' ? body : JSON.stringify(body)}`;
  }
